<script>import {dollars} from '$lib/format.js';export let data;</script><div class="heading"><div><a href="/dashboard">← Dashboard</a><h1>{data.group.name}</h1><p class="muted">{data.group.memberCount} member{data.group.memberCount===1?'':'s'}</p></div><a class="button" href={'/groups/'+data.group.id+'/expenses/new'}>+ Add expense</a></div><section class="card"><div class="title"><h2>Expenses</h2><span class="muted">Equal-split MVP</span></div>{#if data.expenses.length}{#each data.expenses as e}<div class="expense"><span><b>{e.description}</b><small>{e.date} · paid by {e.payerName}</small></span><strong>{dollars(e.amount)}</strong></div>{/each}{:else}<div class="empty"><p>No expenses yet. Add the first shared cost.</p><a class="button secondary" href={'/groups/'+data.group.id+'/expenses/new'}>Add expense</a></div>{/if}</section><style>.heading{align-items:end;display:flex;justify-content:space-between;margin:2rem 0}.heading h1{font-size:2.6rem;margin:.7rem 0 .2rem}.muted,small{color:#58746b}.title{align-items:center;display:flex;justify-content:space-between}.expense{align-items:center;border-top:1px solid #e6efeb;display:flex;justify-content:space-between;padding:1rem 0}.expense span{display:grid;gap:.2rem}.expense strong{color:#146c52}.empty{text-align:center;padding:2rem;color:#58746b}@media(max-width:600px){.heading{align-items:flex-start;gap:1rem;flex-direction:column}}</style>
